/// One CIL opcode. `op1 == 0xff` marks a one-byte opcode whose encoding is
/// `op2`; otherwise the encoding is the two bytes `op1 op2` (op1 is 0xfe).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct OpCode {
    pub code: Code,
    pub op1: u8,
    pub op2: u8,
    pub flow_control: FlowControl,
    pub opcode_type: OpCodeType,
    pub operand_type: OperandType,
    pub stack_pop: StackBehaviour,
    pub stack_push: StackBehaviour,
}

impl OpCode {
    pub fn name(self) -> &'static str {
        NAMES[self.code as usize]
    }

    /// Encoded size in bytes (1 or 2).
    pub fn size(self) -> u32 {
        if self.op1 == 0xff { 1 } else { 2 }
    }

    /// The opcode value as in ECMA-335 (e.g. 0xfe01 for ceq).
    pub fn value(self) -> u16 {
        if self.op1 == 0xff { self.op2 as u16 } else { ((self.op1 as u16) << 8) | self.op2 as u16 }
    }
}

impl std::fmt::Display for OpCode {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.name())
    }
}

